 static void Arrange(FrameworkElement element,double width){element.Measure(new Size(width,double.PositiveInfinity));element.Arrange(new Rect(new Point(),element.DesiredSize));element.UpdateLayout();}
 static IEnumerable<DependencyObject> Descendants(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var c=VisualTreeHelper.GetChild(root,i);yield return c;foreach(var d in Descendants(c))yield return d;}}
 static IEnumerable<DependencyObject> LogicalDescendants(DependencyObject root){foreach(var child in LogicalTreeHelper.GetChildren(root)){if(child is not DependencyObject d)continue;yield return d;foreach(var nested in LogicalDescendants(d))yield return nested;}}
 static Rect Bounds(FrameworkElement element,Visual ancestor)=>element.TransformToAncestor(ancestor).TransformBounds(new Rect(new Point(),element.RenderSize));
